USE talenthub;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('STUDENT','ADMIN') NOT NULL, student_id INT NULL UNIQUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_user_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, CONSTRAINT chk_user_role_link CHECK ((role='STUDENT' AND student_id IS NOT NULL) OR (role='ADMIN' AND student_id IS NULL)));
